@slots literal
{
  "place": "Stadium District",
  "renter": "Gina",
  "staff": "Hugo",
  "termDays": 13,
  "returnDays": 15,
  "lateDays": 2,
  "deposit": 450,
  "depositArticle": 4,
  "latePerDay": 25,
  "batteryLimit": 50,
  "batteryKeep": 30,
  "batteryPercent": 40,
  "scratchCm": 8,
  "changeArticle": 9
}

@answer jsEval
const probe = (condition, message) => { if (!condition) { throw new Error("probe failed: " + message); } };
probe(typeof $slots === "object" && $slots !== null && !Array.isArray($slots), "the compiled slots wire must carry an object");
probe(Object.keys($slots).length > 0, "the compiled slots wire must not be empty");
const answer = await (async () => {
const slots = $slots;
probe(typeof slots === "object" && slots !== null, "the case must carry the parsed contract");
probe(Number.isInteger(slots.termDays) && slots.termDays > 0, "the contracted term must be a whole number of days");
probe(Number.isInteger(slots.lateDays) && slots.lateDays > 0, "the return must be after the contracted term");
probe(Number.isInteger(slots.latePerDay) && slots.latePerDay > 0, "the late fee per calendar day must be positive");
probe(Number.isInteger(slots.batteryPercent) && Number.isInteger(slots.batteryLimit), "the battery charge and its threshold must be whole percentages");
probe(Number.isInteger(slots.depositArticle) && Number.isInteger(slots.changeArticle), "every clause must keep its article number");
probe(slots.depositArticle !== slots.changeArticle, "the deposit clause and the written-changes clause must be different articles");
probe(slots.renter !== slots.staff, "the renter and the staff member must be different people");
const lateTotal = slots.lateDays * slots.latePerDay;
const lateClause = "Late fee " + slots.lateDays + "×" + slots.latePerDay + "=" + lateTotal + ".";
const batteryClause = slots.batteryPercent < slots.batteryLimit
  ? "Battery " + slots.batteryPercent + "%<" + slots.batteryLimit + "% → " + slots.batteryKeep + " from the deposit."
  : "Battery " + slots.batteryPercent + "%≥" + slots.batteryLimit + "% → nothing kept from the deposit.";
const depositClause = "The scratch cancels the duty to return the deposit in full (Art. " + slots.depositArticle + ").";
const speechClause = "Speech does not amend Art. " + slots.changeArticle + ".";
const cashClause = "Return is not “same day cash”.";
return [lateClause, batteryClause, depositClause, speechClause, cashClause].join(" ");
})();
probe(answer !== undefined && answer !== null && String(answer).length > 0, "the computation returned an empty answer");
return answer;

@slots literal
{
  "place": "Forest Parish",
  "author": "Drew",
  "deckPrice": 108,
  "stallsVisited": 3,
  "stallsTotal": 5,
  "lowPrice": 9,
  "highPrice": 11,
  "bowlGrams": 400,
  "bowlPrice": 108,
  "lastYearPrice": 8,
  "townHallQuote": "we have received no written complaints",
  "commentOnePrice": 108
}

@answer jsEval
const probe = (condition, message) => { if (!condition) { throw new Error("probe failed: " + message); } };
probe(typeof $slots === "object" && $slots !== null && !Array.isArray($slots), "the compiled slots wire must carry an object");
probe(Object.keys($slots).length > 0, "the compiled slots wire must not be empty");
const answer = await (async () => {
const slots = $slots;
probe(typeof slots === "object" && slots !== null, "the case must carry the parsed story");
probe(typeof slots.place === "string" && slots.place.length > 0, "the headline must name the market town");
probe(typeof slots.author === "string" && slots.author.length > 0, "the body must be signed");
probe(Number.isInteger(slots.stallsVisited) && Number.isInteger(slots.stallsTotal), "the sample must count whole stalls");
probe(slots.stallsVisited > 0 && slots.stallsVisited < slots.stallsTotal, "the sample must visit some, not all, of the stalls");
probe(slots.lowPrice < slots.highPrice, "the field prices must form a range, not one price");
probe(slots.deckPrice === slots.bowlPrice, "the deck must quote the single tasting bowl");
probe(slots.commentOnePrice === slots.bowlPrice, "the first comment must repeat the deck price");
const words = ["zero", "one", "two", "three", "four", "five", "six", "seven", "eight", "nine", "ten"];
const sample = words[slots.stallsTotal] ?? String(slots.stallsTotal);
const bodyClause = "Body: a sample of " + sample + " stalls, one day; " + slots.lowPrice + "–" + slots.highPrice + " a kilo for field fruit; one " + slots.bowlGrams + " g tasting bowl at " + slots.bowlPrice + " a kilo.";
const headlineClause = "The headline generalises.";
const fieldIsUniform = slots.lowPrice === slots.highPrice;
const firstCommentFollows = fieldIsUniform && slots.commentOnePrice === slots.lowPrice;
const secondCommentFollows = /price/.test(slots.townHallQuote);
const reasons = [];
if (!firstCommentFollows) { reasons.push("the first treats the headline as the body"); }
if (!secondCommentFollows) { reasons.push("the second confuses “no complaints” with “no prices”"); }
const lead = !firstCommentFollows && !secondCommentFollows ? "Neither comment follows" : firstCommentFollows && secondCommentFollows ? "Both comments follow" : "One comment follows";
const commentsClause = reasons.length === 0 ? lead + "." : lead + ": " + reasons.join("; ") + ".";
return bodyClause + " " + headlineClause + " " + commentsClause;
})();
probe(answer !== undefined && answer !== null && String(answer).length > 0, "the computation returned an empty answer");
return answer;

