  "reportTime": "18:25",
  "reportRunner": "Ann",
  "shopFloor": 12,
  "tookOnlyLoaves": true,
  "stopTime": "18:26",
  "stopSaysBuy": false,
  "sentTime": "18:25",
  "walkMinutes": 8,
  "unreadTime": "18:26"
}

